-- Project Baca — development catalog seed (dev only, never production).
--
-- Four short original works under CC0 so the local catalog reads like a
-- library instead of test debris. Fixed ids make the seed idempotent and let
-- the web test suite pin a book (`crates/web/tests/conftest.py`). Covers are
-- empty on purpose: the typographic plate renders them.
--
-- Usage: make seed-dev

BEGIN;

INSERT INTO books (id, title, author, language, primary_theme, sub_theme, description, cover_url,
                   epub_storage_path, total_words, estimated_reading_minutes, source_name, source_url,
                   license, publication_year, status)
VALUES
  ('a0000000-0000-4000-8000-000000000001', 'Surat dari Pelabuhan Teluk', 'N. Larasati', 'id', 'Romansa', 'Surat-menyurat',
   'Dua sahabat masa kecil dipisahkan laut dan menyambung hidup lewat surat yang datang sebulan sekali. Sebuah kisah tentang kesetiaan kata-kata.',
   '', 'seed/surat-dari-pelabuhan-teluk.epub', 3600, 16, 'Pustaka Rotaria', NULL, 'CC0-1.0', 1931, 'published'),
  ('a0000000-0000-4000-8000-000000000002', 'Peta yang Tidak Pernah Selesai', 'Hadi Wiraatmadja', 'id', 'Petualangan', 'Ekspedisi',
   'Seorang juru gambar ikut ekspedisi menyusuri sungai pedalaman untuk menyelesaikan peta yang ditinggalkan ayahnya setengah jadi.',
   '', 'seed/peta-yang-tidak-pernah-selesai.epub', 3600, 16, 'Pustaka Rotaria', NULL, 'CC0-1.0', 1927, 'published'),
  ('a0000000-0000-4000-8000-000000000003', 'Lampu di Rumah Juru Tulis', 'Teguh Prasojo', 'id', 'Misteri', 'Kota kecil',
   'Setiap malam lampu di rumah juru tulis menyala sampai subuh, padahal pemiliknya sudah lama pergi. Warga mulai bertanya siapa yang menulis.',
   '', 'seed/lampu-di-rumah-juru-tulis.epub', 3600, 16, 'Pustaka Rotaria', NULL, 'CC0-1.0', 1935, 'published'),
  ('a0000000-0000-4000-8000-000000000004', 'The Quiet Ledger', 'Eleanor Whitcombe', 'en', 'Memoir', 'Working life',
   'A bookkeeper in a harbour town records a year of small accounts and discovers that the sums she keeps are not the ones that matter.',
   '', 'seed/the-quiet-ledger.epub', 3600, 16, 'Pustaka Rotaria', NULL, 'CC0-1.0', 1912, 'published')
